use verus::*;

verus! {

    // Given two integer slices `a` and `b` of equal positive length,
    // both sorted in nondecreasing order,
    // return the median defined as:
    // - if length is odd, median is the middle element of `a`
    // - if even, median is integer average (floor division) of last element
    //   of lower half of `a` and first element of `b`.
    //
    // The function includes full specifications,
    // including sortedness, length, and correctness of median.

    #[allow(unused)]
    fn find_median(a: &[i32], b: &[i32]) -> (median: i32)
        requires
            a.len() == b.len(),
            a.len() > 0,
            is_nondec_sorted(a),
            is_nondec_sorted(b),
        ensures
            if a.len() % 2 == 1 {
                // odd length: median = middle element of a
                median == a[a.len() / 2]
            } else {
                // even length:
                // median = integer average of last element of lower half of a and first element of b
                let half = a.len() / 2;
                median == int_avg(a[half - 1], b[0])
            }
    {
        let n = a.len();

        if n % 2 == 1 {
            // odd length: return middle element of `a`
            median = a[n / 2];
            assert(median == a[n / 2]);
        } else {
            // even length
            let half = n / 2;
            let x = a[half - 1];
            let y = b[0];
            median = int_avg(x, y);
            assert(median == (x + y).div_euclid(2));
        }
    }

    // Helper function: integer average of two i32 with floor division semantics
    #[verifier(inline)]
    fn int_avg(x: i32, y: i32) -> i32 {
        // Using div_euclid for floor division behavior.
        // (x + y) / 2, rounded down for negatives.
        (x + y).div_euclid(2)
    }

    // Predicate: the slice a is sorted in nondecreasing order
    #[verifier(external_body)]
    fn is_nondec_sorted(a: &[i32]) -> bool {
        forall |i: usize, j: usize| (i < j && j < a.len()) ==> a[i] <= a[j]
    }

}